SELECT CASE WHEN cost >= 78 THEN 'HIGH' ELSE 'LOW' END AS cost_tier, DATE_TRUNC('WEEK', shipped_date) AS week_start, COUNT(*) AS event_count, SUM(CASE WHEN status = 'DELIVERED' THEN cost ELSE 0 END) AS delivered_cost, COUNT(*) AS row_count, COUNT(CASE WHEN status = 'DELIVERED' THEN 1 END) AS delivered_count, MAX(cost) FILTER (WHERE carrier = 'Flash') AS flash_max_cost, STDDEV_SAMP(cost) AS cost_stddev, GROUPING_ID() AS grouping_level FROM shipments GROUP BY GROUPING SETS ((CASE WHEN cost >= 78 THEN 'HIGH' ELSE 'LOW' END, DATE_TRUNC('WEEK', shipped_date)), (CASE WHEN cost >= 78 THEN 'HIGH' ELSE 'LOW' END), ()) HAVING cost_stddev >= 0 ORDER BY cost_stddev DESC NULLS LAST
